//! Deterministic demo backend for the board (`"source": "demo"`).
//!
//! It stands in for the SPM daemon, which has no board producer yet, and answers
//! with the same contract envelopes: `Event::Board`, `GetCardEvidence`,
//! `Refresh` + `OperationCompleted`, `BuildBriefing` and `ResolveNavigation`.
//! Each refresh advances one scripted revision of the Orion scenario. The data is
//! fictional and generated by `scripts/generate_board_fixtures.py`.

use super::model::{DisplayColumn, Signal, degraded_sources, label_of, signals};
use super::text::{Lang, short_time};
use pecofence_plugin_api::{Error, PanelEvent, Result, Token};
use spm_contracts::{
    BoardSnapshot, Body, BriefingId, BuildBriefingResponse, CardEvidenceResponse, DaemonSessionId,
    Envelope, ErrorCode, ErrorDto, Event, EvidenceMarker, OperationCompleted, OperationId,
    PROTOCOL_MAJOR, PROTOCOL_MINOR, RefreshDisposition, RefreshOutcome, RefreshResponse, Request,
    RequestId, ResolveNavigationResponse, Response, SubscriptionId,
};
use std::sync::Arc;
use std::time::{Duration, Instant};

const STEPS: [(&str, &str); 3] = [
    (
        include_str!("../../fixtures/board-demo/step1-board.json"),
        include_str!("../../fixtures/board-demo/step1-evidence.json"),
    ),
    (
        include_str!("../../fixtures/board-demo/step2-board.json"),
        include_str!("../../fixtures/board-demo/step2-evidence.json"),
    ),
    (
        include_str!("../../fixtures/board-demo/step3-board.json"),
        include_str!("../../fixtures/board-demo/step3-evidence.json"),
    ),
];

/// What each scripted revision shows, for the demo banner.
pub const STEP_NOTES: [&str; 3] = [
    "After Gale's reply in Lark (10-26 10:20)",
    "After the Meegle owner update (10-27 14:10)",
    "Meegle refreshed, Gerrit failed (10-27 14:25)",
];

/// Delays make loading states visible; tests pass their own clock.
pub const FIRST_SNAPSHOT: Duration = Duration::from_millis(450);
pub const RESPONSE: Duration = Duration::from_millis(150);
pub const REFRESH_WORK: Duration = Duration::from_millis(900);
pub const EVIDENCE: Duration = Duration::from_millis(350);

pub fn step_board(step: usize) -> BoardSnapshot {
    serde_json::from_str(STEPS[step].0).expect("demo board fixture")
}

pub fn step_evidence(step: usize) -> Vec<CardEvidenceResponse> {
    serde_json::from_str(STEPS[step].1).expect("demo evidence fixture")
}

pub fn step_count() -> usize {
    STEPS.len()
}

pub struct DemoBackend {
    step: usize,
    session: u128,
    subscription: Option<(Token, SubscriptionId)>,
    next_token: u64,
    queue: Vec<(Instant, PanelEvent)>,
    /// One evidence request fails once, to show the failed state and retry.
    failed_once: bool,
}

impl Default for DemoBackend {
    fn default() -> Self {
        Self::new()
    }
}

impl DemoBackend {
    pub fn new() -> Self {
        Self {
            step: 0,
            session: 0x2222_2222_2222_4222_8222_0000_0000_0001,
            subscription: None,
            // Far from host token ranges; the panel only compares tokens it was given.
            next_token: 1 << 62,
            queue: Vec::new(),
            failed_once: false,
        }
    }

    pub fn step(&self) -> usize {
        self.step
    }

    fn token(&mut self) -> Token {
        self.next_token += 1;
        Token(self.next_token)
    }

    fn session(&self) -> DaemonSessionId {
        DaemonSessionId(uuid::Uuid::from_u128(self.session))
    }

    pub fn subscribe(&mut self, now: Instant) -> Token {
        let token = self.token();
        self.subscription = Some((token, SubscriptionId::new()));
        self.push_board(now + FIRST_SNAPSHOT);
        token
    }

    /// Start the script again as a new daemon session (revisions restart).
    pub fn restart(&mut self, now: Instant) {
        self.step = 0;
        self.session += 1;
        self.failed_once = false;
        self.queue
            .retain(|(_, event)| !matches!(event, PanelEvent::Snapshot { .. }));
        self.push_board(now + RESPONSE);
    }

    fn board(&self) -> BoardSnapshot {
        let mut board = step_board(self.step);
        board.daemon_session = self.session();
        board
    }

    fn push_board(&mut self, at: Instant) {
        let Some((token, subscription)) = self.subscription else {
            return;
        };
        let board = self.board();
        let envelope = Envelope {
            protocol_major: PROTOCOL_MAJOR,
            protocol_minor: PROTOCOL_MINOR,
            daemon_session: Some(board.daemon_session),
            request_id: None,
            subscription_id: Some(subscription),
            revision: Some(board.revision),
            body: Body::Event(Event::Board(board)),
        };
        self.queue.push((
            at,
            PanelEvent::Snapshot {
                subscription: token,
                bytes: encode(&envelope),
            },
        ));
    }

    fn reply(&mut self, at: Instant, operation: Token, body: Body) {
        let envelope = Envelope {
            protocol_major: PROTOCOL_MAJOR,
            protocol_minor: PROTOCOL_MINOR,
            daemon_session: Some(self.session()),
            request_id: Some(RequestId::new()),
            subscription_id: None,
            revision: None,
            body,
        };
        let envelope = match envelope.body {
            Body::Error(mut error) => {
                error.request_id = envelope.request_id;
                Envelope {
                    body: Body::Error(error),
                    ..envelope
                }
            }
            _ => envelope,
        };
        self.queue.push((
            at,
            PanelEvent::Completion {
                operation,
                result: Ok(encode(&envelope)),
            },
        ));
    }

    /// Accept one request payload (a JSON `Request`, as for the host IPC).
    pub fn send(&mut self, payload: &[u8], now: Instant) -> Result<Token> {
        let request: Request =
            serde_json::from_slice(payload).map_err(|error| Error::Invalid(error.to_string()))?;
        request
            .validate()
            .map_err(|error| Error::Invalid(error.to_string()))?;
        let operation = self.token();
        let board = self.board();
        match request {
            Request::Refresh(_) => {
                let id = OperationId::new();
                self.reply(
                    now + RESPONSE,
                    operation,
                    Body::Response(Response::Refresh(RefreshResponse {
                        operation_id: id,
                        disposition: RefreshDisposition::Accepted,
                    })),
                );
                let at = now + REFRESH_WORK;
                if self.step + 1 < STEPS.len() {
                    self.step += 1;
                    self.push_board(at);
                }
                self.push_completed(at, id);
            }
            Request::GetCardEvidence(request) => {
                let response = step_evidence(self.step)
                    .into_iter()
                    .find(|r| r.card_id == request.card_id);
                let fail_now = !self.failed_once
                    && board.cards.iter().any(|c| {
                        c.card_id == request.card_id
                            && c.business_number.as_deref() == Some("ORION-R-121")
                    });
                let body = match response {
                    _ if request.revision != board.revision => Body::Error(error(
                        ErrorCode::SnapshotExpired,
                        "the board has a newer revision",
                    )),
                    _ if fail_now => {
                        self.failed_once = true;
                        Body::Error(error(
                            ErrorCode::Unavailable,
                            "Meegle did not answer in time",
                        ))
                    }
                    Some(response) => Body::Response(Response::GetCardEvidence(response)),
                    None => Body::Error(error(ErrorCode::NotFound, "no such card")),
                };
                self.reply(now + EVIDENCE, operation, body);
            }
            Request::BuildBriefing(request) => {
                let body = if request.revision != board.revision {
                    Body::Error(error(
                        ErrorCode::SnapshotExpired,
                        "the board has a newer revision",
                    ))
                } else {
                    Body::Response(Response::BuildBriefing(briefing(
                        &board,
                        Lang::for_locale(&request.locale),
                    )))
                };
                self.reply(now + RESPONSE, operation, body);
            }
            Request::ResolveNavigation(_) => {
                // Demo records are fictional, so no navigation origin is configured.
                self.reply(
                    now + RESPONSE,
                    operation,
                    Body::Response(Response::ResolveNavigation(ResolveNavigationResponse {
                        targets: Vec::new(),
                    })),
                );
            }
            other => {
                return Err(Error::Invalid(format!(
                    "the demo backend does not serve {:?}",
                    other.method()
                )));
            }
        }
        Ok(operation)
    }

    fn push_completed(&mut self, at: Instant, operation_id: OperationId) {
        let Some((token, _)) = self.subscription else {
            return;
        };
        let now = chrono::Utc::now();
        let envelope = Envelope {
            protocol_major: PROTOCOL_MAJOR,
            protocol_minor: PROTOCOL_MINOR,
            daemon_session: Some(self.session()),
            request_id: None,
            subscription_id: None,
            revision: None,
            body: Body::Event(Event::OperationCompleted(OperationCompleted {
                operation_id,
                outcome: RefreshOutcome::Completed,
                started_at: now,
                finished_at: now,
                error: None,
            })),
        };
        self.queue.push((
            at,
            PanelEvent::Snapshot {
                subscription: token,
                bytes: encode(&envelope),
            },
        ));
    }

    pub fn cancel(&mut self, token: Token) {
        self.queue.retain(|(_, event)| match event {
            PanelEvent::Completion { operation, .. } => *operation != token,
            _ => true,
        });
    }

    /// Events due at `now`, in delivery order.
    pub fn due(&mut self, now: Instant) -> Vec<PanelEvent> {
        self.queue.sort_by_key(|(at, _)| *at);
        let split = self.queue.partition_point(|(at, _)| *at <= now);
        self.queue.drain(..split).map(|(_, event)| event).collect()
    }

    pub fn next_due(&self, now: Instant) -> Option<Duration> {
        self.queue
            .iter()
            .map(|(at, _)| at.saturating_duration_since(now))
            .min()
    }
}

fn error(code: ErrorCode, message: &str) -> ErrorDto {
    ErrorDto {
        code,
        request_id: None,
        retryable: matches!(code, ErrorCode::Unavailable),
        message: message.into(),
        details: None,
    }
}

fn encode(envelope: &Envelope) -> Arc<[u8]> {
    Arc::from(serde_json::to_vec(envelope).expect("demo envelope serializes"))
}

/// The meeting summary the backend would build: counts, what needs a decision,
/// next actions grouped by person, and evidence markers. Plain text.
pub fn briefing(board: &BoardSnapshot, lang: Lang) -> BuildBriefingResponse {
    let tz = board.project_timezone.as_str();
    let degraded = degraded_sources(board);
    let mut text = format!(
        "{} · {} — {} (rev {})\n",
        board.project_id,
        board.delivery_scope_id,
        lang.f("Data as of {}", &[&short_time(board.computed_at, tz)]),
        board.revision.0
    );
    let counts: Vec<String> = DisplayColumn::ALL
        .iter()
        .map(|column| {
            let n = board
                .cards
                .iter()
                .filter(|c| DisplayColumn::of(c.stage.stage) == *column)
                .count();
            (column, n)
        })
        .filter(|(_, n)| *n > 0)
        .map(|(column, n)| {
            let prefix = if board.totals_complete { "" } else { "≥" };
            format!("{} {prefix}{n}", column.label(lang))
        })
        .collect();
    text.push_str(&counts.join(" · "));
    text.push('\n');
    for system in &degraded {
        text.push_str(&format!(
            "! {}\n",
            lang.f("{} did not refresh", &[super::model::system_label(*system)])
        ));
    }
    let mut markers = Vec::new();
    let attention: Vec<_> = board
        .cards
        .iter()
        .filter_map(|card| {
            let s = signals(card, &degraded);
            s.iter()
                .copied()
                .find(|s| s.needs_attention() && *s != Signal::SourceNotRefreshed)
                .map(|signal| (card, signal))
        })
        .collect();
    if !attention.is_empty() {
        text.push_str(&format!("\n{}\n", lang.t("Needs attention")));
        for (card, signal) in attention {
            let n = markers.len() + 1;
            text.push_str(&format!(
                "- {} {} — {} [{n}]\n",
                label_of(card),
                card.title,
                super::model::signal_text(card, signal, lang)
            ));
            markers.push(EvidenceMarker {
                label: format!("[{n}]"),
                source_refs: vec![card.source.clone()],
            });
        }
    }
    let mut owners: Vec<(String, Vec<String>)> = Vec::new();
    for card in &board.cards {
        let Some(action) = &card.next_action else {
            continue;
        };
        let owner = action.owner.as_ref().map_or_else(
            || lang.t("Unassigned").to_owned(),
            |o| o.display_name.clone(),
        );
        let line = format!("{}: {}", label_of(card), action.text);
        match owners.iter_mut().find(|(name, _)| *name == owner) {
            Some((_, lines)) => lines.push(line),
            None => owners.push((owner, vec![line])),
        }
    }
    if !owners.is_empty() {
        text.push_str(&format!("\n{}\n", lang.t("Next action")));
        for (owner, lines) in owners {
            text.push_str(&format!("{owner}\n"));
            for line in lines {
                text.push_str(&format!("  - {line}\n"));
            }
        }
    }
    BuildBriefingResponse {
        briefing_id: BriefingId::new(),
        revision: board.revision,
        text,
        html: None,
        evidence_markers: markers,
    }
}
